// 'use client' in Next.js
function App() {
  const [theme, setTheme] = useState('light'); // safe default for the server render
  useEffect(() => {
    // localStorage only exists in the browser, so read it after mount
    const saved = (typeof localStorage !== 'undefined' && localStorage.getItem('theme')) || 'light';
    setTheme(saved);
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Current theme: <b>{theme}</b></p>
      <button onClick={() => {
        const next = theme === 'light' ? 'dark' : 'light';
        setTheme(next);
        if (typeof localStorage !== 'undefined') localStorage.setItem('theme', next);
      }}>Toggle theme</button>
    </div>
  );
}

