// 'use client' — but it reads a browser API DURING render
function App() {
  // window doesn't exist on the server, and even if guarded it differs from the
  // server HTML, so hydration mismatches:
  const width = typeof window !== 'undefined' ? window.innerWidth : 0;
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Viewport width: {width}px</p>
    </div>
  );
}

solution.code:
// 'use client'
function App() {
  const [width, setWidth] = useState(null); // matches server (no browser value yet)
  useEffect(() => {
    const update = () => setWidth(window.innerWidth);
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Viewport width: {width == null ? '…' : width + 'px'}</p>
    </div>
  );
}

// app/people/Search.tsx
'use client';
import { useState } from 'react';

export function Search({ people }: { people: string[] }) {
  const [q, setQ] = useState('');
  const shown = people.filter((p) => p.toLowerCase().includes(q.toLowerCase()));
  return (
    <div>
      <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Filter…" />
      <ul>{shown.map((p) => <li key={p}>{p}</li>)}</ul>
    </div>
  );
}

